{
  "name": "@expnn/opencode-yaml-hooks",
  "version": "2.1.0",
  "description": "OpenCode plugin for running command, tool, and bash hooks from hooks.yaml during session and tool lifecycle events.",
  "type": "module",
  "main": "index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./index.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./tui.js"
    },
    "./rpc": {
      "types": "./dist/rpc.d.ts",
      "import": "./rpc.js"
    }
  },
  "files": [
    "index.js",
    "tui.js",
    "rpc.js",
    "dist",
    "README.md"
  ],
  "scripts": {
    "build": "bun build src/index.ts src/tui.ts src/rpc.ts --outdir . --target bun --format esm && tsc -p tsconfig.json --emitDeclarationOnly",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "vitest run"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "hooks",
    "automation",
    "workflow",
    "tooling",
    "plugin",
    "runtime"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/expnn/opencode-yaml-hooks.git"
  },
  "homepage": "https://github.com/expnn/opencode-yaml-hooks#readme",
  "bugs": {
    "url": "https://github.com/expnn/opencode-yaml-hooks/issues"
  },
  "license": "MIT",
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.29 <2"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.29",
    "@opencode/plugin": "2.0.18",
    "@types/node": "^25.5.0",
    "typescript": "^5.9.3",
    "vitest": "^4.0.17"
  },
  "dependencies": {
    "yaml": "^2.8.2"
  }
}
